-- Migração inicial gerada a partir de prisma/schema.prisma.
CREATE TABLE "Usuario" ("id" TEXT NOT NULL PRIMARY KEY, "nome" TEXT NOT NULL, "nomeUsuario" TEXT NOT NULL, "senhaHash" TEXT NOT NULL, "papel" TEXT NOT NULL, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadoEm" DATETIME NOT NULL);
