CREATE TABLE "PerfilProfessor" ("id" TEXT NOT NULL PRIMARY KEY, "usuarioId" TEXT NOT NULL, CONSTRAINT "PerfilProfessor_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "Usuario" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Turma" ("id" TEXT NOT NULL PRIMARY KEY, "nome" TEXT NOT NULL, "periodo" TEXT NOT NULL, "professorId" TEXT NOT NULL, "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Turma_professorId_fkey" FOREIGN KEY ("professorId") REFERENCES "PerfilProfessor" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Matricula" ("id" TEXT NOT NULL PRIMARY KEY, "alunoId" TEXT NOT NULL, "turmaId" TEXT NOT NULL, "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Matricula_alunoId_fkey" FOREIGN KEY ("alunoId") REFERENCES "PerfilAluno" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Matricula_turmaId_fkey" FOREIGN KEY ("turmaId") REFERENCES "Turma" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Topico" ("id" TEXT NOT NULL PRIMARY KEY, "identificador" TEXT NOT NULL, "nome" TEXT NOT NULL, "descricao" TEXT NOT NULL, "ativo" BOOLEAN NOT NULL DEFAULT true, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RecursoConteudo" ("id" TEXT NOT NULL PRIMARY KEY, "identificador" TEXT NOT NULL, "titulo" TEXT NOT NULL, "descricao" TEXT NOT NULL, "formato" TEXT NOT NULL, "minutosEstimados" INTEGER NOT NULL, "topicoId" TEXT NOT NULL, "url" TEXT, "ativo" BOOLEAN NOT NULL DEFAULT true, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadoEm" DATETIME NOT NULL, CONSTRAINT "RecursoConteudo_topicoId_fkey" FOREIGN KEY ("topicoId") REFERENCES "Topico" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "AprovacaoRecurso" ("id" TEXT NOT NULL PRIMARY KEY, "recursoId" TEXT NOT NULL, "professorId" TEXT NOT NULL, "situacao" TEXT NOT NULL DEFAULT 'PENDENTE', "observacao" TEXT, "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadaEm" DATETIME NOT NULL, CONSTRAINT "AprovacaoRecurso_recursoId_fkey" FOREIGN KEY ("recursoId") REFERENCES "RecursoConteudo" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "AprovacaoRecurso_professorId_fkey" FOREIGN KEY ("professorId") REFERENCES "PerfilProfessor" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SessaoEstudo" ("id" TEXT NOT NULL PRIMARY KEY, "alunoId" TEXT NOT NULL, "topicoId" TEXT NOT NULL, "recursoId" TEXT NOT NULL, "iniciadaEm" DATETIME NOT NULL, "encerradaEm" DATETIME, "duracaoMinutos" INTEGER, "situacao" TEXT NOT NULL DEFAULT 'ATIVA', "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SessaoEstudo_alunoId_fkey" FOREIGN KEY ("alunoId") REFERENCES "PerfilAluno" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SessaoEstudo_topicoId_fkey" FOREIGN KEY ("topicoId") REFERENCES "Topico" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "SessaoEstudo_recursoId_fkey" FOREIGN KEY ("recursoId") REFERENCES "RecursoConteudo" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Avaliacao" ("id" TEXT NOT NULL PRIMARY KEY, "identificador" TEXT NOT NULL, "titulo" TEXT NOT NULL, "descricao" TEXT NOT NULL, "topicoId" TEXT NOT NULL, "ativa" BOOLEAN NOT NULL DEFAULT true, "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Avaliacao_topicoId_fkey" FOREIGN KEY ("topicoId") REFERENCES "Topico" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Questao" ("id" TEXT NOT NULL PRIMARY KEY, "avaliacaoId" TEXT NOT NULL, "enunciado" TEXT NOT NULL, "opcoesJson" TEXT NOT NULL, "opcaoCorreta" TEXT NOT NULL, "posicao" INTEGER NOT NULL, "peso" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "Questao_avaliacaoId_fkey" FOREIGN KEY ("avaliacaoId") REFERENCES "Avaliacao" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "TentativaAvaliacao" ("id" TEXT NOT NULL PRIMARY KEY, "alunoId" TEXT NOT NULL, "avaliacaoId" TEXT NOT NULL, "topicoId" TEXT NOT NULL, "iniciadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "concluidaEm" DATETIME, "respostasCorretas" INTEGER NOT NULL DEFAULT 0, "totalQuestoes" INTEGER NOT NULL DEFAULT 0, "notaNormalizada" REAL, "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TentativaAvaliacao_alunoId_fkey" FOREIGN KEY ("alunoId") REFERENCES "PerfilAluno" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "TentativaAvaliacao_avaliacaoId_fkey" FOREIGN KEY ("avaliacaoId") REFERENCES "Avaliacao" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "RespostaQuestao" ("id" TEXT NOT NULL PRIMARY KEY, "tentativaId" TEXT NOT NULL, "questaoId" TEXT NOT NULL, "resposta" TEXT NOT NULL, "correta" BOOLEAN NOT NULL, "pontos" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "RespostaQuestao_tentativaId_fkey" FOREIGN KEY ("tentativaId") REFERENCES "TentativaAvaliacao" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "RespostaQuestao_questaoId_fkey" FOREIGN KEY ("questaoId") REFERENCES "Questao" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Recomendacao" ("id" TEXT NOT NULL PRIMARY KEY, "alunoId" TEXT NOT NULL, "topicoId" TEXT NOT NULL, "recursoId" TEXT, "formatoSugerido" TEXT NOT NULL, "justificativa" TEXT NOT NULL, "nivelEvidencia" TEXT NOT NULL, "quantidadeEvidencias" INTEGER NOT NULL, "notaComparada" REAL, "versaoAlgoritmo" TEXT NOT NULL, "situacao" TEXT NOT NULL DEFAULT 'PENDENTE', "criadaEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiraEm" DATETIME, CONSTRAINT "Recomendacao_alunoId_fkey" FOREIGN KEY ("alunoId") REFERENCES "PerfilAluno" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Recomendacao_recursoId_fkey" FOREIGN KEY ("recursoId") REFERENCES "RecursoConteudo" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "EventoAuditoria" ("id" TEXT NOT NULL PRIMARY KEY, "atorId" TEXT, "acao" TEXT NOT NULL, "alvo" TEXT NOT NULL, "metadados" TEXT, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EventoAuditoria_atorId_fkey" FOREIGN KEY ("atorId") REFERENCES "Usuario" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
